{
  "title": "1立方米为什么是1000000立方厘米——只数边长和小方块",
  "goal": "这一轮只解决立方单位换算：把棱长1 m的大立方体看成由棱长1 cm的小方块填满，用“底面一层有多少个×有多少层”得到100×100×100，理解为什么是100万而不是100或300；不重讲密度计算。",
  "steps": [
    {
      "title": "先只看一条棱：1 m里有100个1 cm",
      "explanation": "1 cm³是棱长1 cm的小方块；1 m³是棱长1 m的大立方体。先别看整个大立方体，只看一条棱：1 m=100 cm，所以大立方体的一条棱上可以排100个1 cm长的小段，也就是100个小方块的棱长。",
      "question": "不数整个大立方体，只看它的一条棱：1 m长的棱上能排多少个棱长1 cm的小方块？为什么？",
      "checkpoint": "能回答100个，并说出依据是1 m=100 cm。"
    },
    {
      "title": "看底面一层：100排，每排100个",
      "explanation": "大立方体的底面是1 m×1 m。把底面想成格子：长边排100个小方块，宽边也排100个小方块。每一排有100个，共有100排，所以底面一层是100×100=10000个小方块。这里用乘法，不是100+100。",
      "question": "底面一层的小方块数为什么写成100×100？其中两个100分别对应底面的什么方向？",
      "checkpoint": "能说一个100对应长边，一个100对应宽边；底层共10000个。"
    },
    {
      "title": "别忘了高度：要堆100层",
      "explanation": "一个小方块高1 cm。大立方体的高是1 m=100 cm，所以从底到顶要堆100层。刚才的10000个只是最下面一层；如果只铺一层，高度只有1 cm，还没有到1 m。",
      "question": "底面已经铺了10000个小方块，为什么还不能说大立方体已经填满？还缺哪个方向？",
      "checkpoint": "能指出还缺高度方向，需要100层，每层高1 cm。"
    },
    {
      "title": "把一层乘层数：10000×100",
      "explanation": "每层10000个，共100层，所以总块数是10000×100=1000000。把底层写成100×100，就得到100×100×100=1000000。三个100分别来自长、宽、高三个方向。",
      "question": "请用“每层多少个×多少层”列式，并说明为什么不是算完100×100就结束。",
      "checkpoint": "能列出10000×100或100×100×100，并说明第三个100来自高度方向的100层，总数为1000000。"
    },
    {
      "title": "100万个小方块合起来就是1 m³",
      "explanation": "每个小方块的体积是1 cm³。大立方体里正好有1000000个这样的小方块，所以它的体积是1000000 cm³。另一方面，这个大立方体的棱长是1 m，体积记作1 m³。两种说法指同一个大立方体，因此1 m³=1000000 cm³。",
      "question": "如果每个小方块的体积是1 cm³，那么1000000个小方块的总体积是多少？它和棱长1 m的大立方体是什么关系？",
      "checkpoint": "能说总体积是1000000 cm³，正好等于1 m³，因此1 m³=1000000 cm³。"
    },
    {
      "title": "长度乘100，体积要三个方向都乘100",
      "explanation": "长度换算只沿一个方向，所以1 m=100 cm。面积有长和宽两个方向：1 m²=100×100 cm²=10000 cm²。体积有长、宽、高三个方向：1 m³=100×100×100 cm³=1000000 cm³。不是把100加三次得到300，因为三个方向不是并排放三条边，而是要把整个空间都用小方块填满。",
      "question": "请比较1 m、1 m²、1 m³的换算：为什么从长度到面积多乘一个100，从面积到体积又多乘一个100？",
      "checkpoint": "能说长度一个方向；面积有长和宽两个方向；体积有长、宽、高三个方向，每个方向都贡献一个100，因此体积倍率是100×100×100。"
    }
  ],
  "parent_tips": [
    "这次先不回到密度。让孩子用手指沿大立方体的长、宽、高各走一遍，每走一条边就问：“这条边上有几个1 cm小段？”确认三条边都是100。",
    "数底层时不要急着说10000，先问：“一排几个？有几排？”等孩子自己说出100×100，再进入高度和层数。",
    "如果孩子漏掉高度，拿一摞方糖或积木只铺一层，问：“现在高度才多少？要到1 m还差多少层？”帮助他看见第三个100。",
    "孩子说出100×100×100后，追问他每个100分别管哪个方向；重点听解释，不只看最后的数字。"
  ],
  "understanding_checks": [
    "只看一条棱、底面一层和高度三个方向：请说出小方块总数应怎样列式，并说明每个100对应哪个方向。",
    "有同学说：“1 m=100 cm，所以1 m³=100 cm³。”你准备用哪两个数量来反驳他？请说出你的计数过程。"
  ],
  "practice": [
    {
      "id": "volume-unit-1",
      "prompt": "一个棱长1 m的正方体容器，用棱长1 cm的小正方体来填满。小明先铺满底面一层，数出100×100=10000个小正方体，就说：“所以1 m³=10000 cm³。”\n请回答：\n(1) 小明漏掉了哪个方向？\n(2) 这个方向上有多少层？每层高多少厘米？\n(3) 正确的总个数是多少？请写出乘式。\n(4) 因此1 m³等于多少cm³？",
      "purpose": "检查是否真正把“底面一层”和“高度层数”分开计数，避免只算底面就结束。",
      "hints": [
        "底面一层铺完后，大立方体只到了1 cm高。",
        "1 m=100 cm，所以从底到顶可以有100层，每层高1 cm。",
        "每层有10000个小正方体，再用每层数量乘层数。"
      ],
      "success_criteria": [
        "能指出小明漏掉了高度方向。",
        "能说出高度方向有100层，每层高1 cm。",
        "能列出10000×100或100×100×100，并得到1000000个小正方体。",
        "能得出1 m³=1000000 cm³，并说明这与100万个小正方体总体积为1000000 cm³一致。"
      ]
    }
  ],
  "recap": "把1 m³看成一个棱长1 m的大立方体：每条棱上有100个1 cm小段；底面一层有100×100个1 cm³小方块；高度方向有100层；所以总共有100×100×100=1000000个小方块，得到1 m³=1000000 cm³。关键不是把100加三次，而是长、宽、高三个方向各乘一次100。"
}
